// Parse and validate input
const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

const CHUNK_THRESHOLD = 10000;

// Generate job_id if not provided
const jobIdProvided = !!body.job_id;
const jobId = body.job_id || 'job_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);
const projectId = headers['x-project-id'] || body.project_id || 'default';

// Determine pipeline type
let pipelineType = 'unknown';
let segments = [];
let needsChunking = false;
let totalSegments = 0;

if (body.segments && Array.isArray(body.segments) && body.segments.length > 0) {
  // Batch mode: multiple segments (commentaries)
  pipelineType = 'batch';
  segments = body.segments.map((s, idx) => ({
    index: idx,
    text: typeof s === 'string' ? s : (s.text || s.text_hebrew || s.hebrew_text),
    segment_id: s.segment_id || null,
    commentary_id: s.commentary_id || null,
    source_text: typeof s === 'string' ? s : null,
    // RFC bilingual-translations-en-pivot: EN pivot for quality
    reference_translation: s.reference_translation || null,
    char_count: (typeof s === 'string' ? s : (s.text || s.text_hebrew || s.hebrew_text || '')).length
  }));

  // Les segments trop longs ne sont plus rejetés : ils seront découpés puis
  // traduits morceau par morceau et RÉASSEMBLÉS (node « Pre-Translate Long »),
  // car le save est keyé par commentary_id (une ligne) — azy.daily#... (chunking batch).
  segments = segments.map(s => ({ ...s, needsChunk: s.char_count > CHUNK_THRESHOLD }));
  totalSegments = segments.length;

} else if (body.text) {
  // Single text mode
  const textLength = body.text.length;

  if (textLength > CHUNK_THRESHOLD) {
    pipelineType = 'chunk_then_translate';
    needsChunking = true;
    // Segments will be created by Chunk Worker
    segments = [{ index: 0, text: body.text, segment_id: body.segment_id || null, source_text: body.text, char_count: textLength }];
    totalSegments = 1; // Will be updated after chunking
  } else {
    pipelineType = 'translate_single';
    segments = [{
      index: 0,
      text: body.text,
      segment_id: body.segment_id || null,
      source_text: body.text,
      char_count: textLength
    }];
    totalSegments = 1;
  }
} else {
  return [{
    json: {
      valid: false,
      error: { code: 400, message: 'Either segments[] or text is required' }
    }
  }];
}

// /api/v2/jobs n'accepte qu'une énumération FERMÉE. Vérifié en direct :
// « translation » (l'ancien défaut ici) et « torah_segment » sont refusés en 422 —
// et Create Job étant en onError=continueRegularOutput, l'échec était avalé :
// aucun job créé, aucune trace, la suite du pipeline patchant un job inexistant.
const JOB_TYPES = ['torah_page', 'torah_commentary', 'torah_unit', 'torah_vocalization',
                   'pdf_translation', 'pdf_summarize', 'image_ocr', 'image_translation'];

// Le type se DÉDUIT de la nature des items : l'appelant n'a pas à connaître notre
// énumération, et une valeur hors énumération ne peut plus casser la création du job.
function deduireJobType(segs, fourni) {
  if (fourni && JOB_TYPES.indexOf(fourni) !== -1) return fourni;
  const aCommentaire = segs.some(s => s.commentary_id);
  const aSegment = segs.some(s => s.segment_id);
  if (aCommentaire && !aSegment) return 'torah_commentary';   // lot de commentaires
  return 'torah_unit';                                        // versets, ou lot mixte
}
const jobTypeDemande = body.job_type || null;

// Identifiant d'appairage fourni par l'appelant (azy.daily#225). Il n'était pas
// relayé : Claude - Call With Skills en générait un autre, et la publication
// Redis partait donc sous un identifiant que l'appelant ne pouvait reconnaître.
// Sa présence conditionne TOUT le mécanisme d'événement — sans lui, rien ne change.
const correlationId = body.correlation_id || null;
const jobType = deduireJobType(segments, jobTypeDemande);

return [{
  json: {
    valid: true,
    useBatch: (Array.isArray(segments) && segments.length > 50),
    jobId: jobId,
    jobIdProvided: jobIdProvided,
    needsJobCreation: !jobIdProvided,
    projectId: projectId,
    jobType: jobType,
    // Conservé pour la traçabilité : dit si une valeur a été écartée.
    jobTypeDemande: jobTypeDemande,
    correlationId: correlationId,
    pipelineType: pipelineType,
    needsChunking: needsChunking,
    segments: segments,
    totalSegments: totalSegments,
    traite: body.traite,
    page: body.page,
    section: body.section,
    commentator: body.commentator,
    sourceLanguage: body.source_language || 'he',
    targetLanguage: body.target_language || 'fr',
    apiKey: body.api_key,
    openaiApiKey: body.openai_api_key,
    context: body.context || {},
    metadata: body.metadata || {},
    requestId: body.request_id,
    model: body.model || 'claude-sonnet-4-6',
    provider: body.provider || 'anthropic',
    chunkThreshold: CHUNK_THRESHOLD
  }
}];

// Prepare segments for translation loop
const input = $('Parse Input').first().json;
const chunkResult = $input.first().json;

let segments = [];

// Check if chunking was done
if (chunkResult.segments && Array.isArray(chunkResult.segments)) {
  // Chunked segments from Chunk Worker
  segments = chunkResult.segments.map((s, idx) => ({
    index: idx,
    text: s.text,
    segment_id: input.segments[0]?.segment_id,
    source_text: input.segments[0]?.source_text,
    char_count: s.text?.length || 0,
    isChunk: true,
    totalChunks: chunkResult.segments.length
  }));
} else {
  // Use original segments (no chunking needed or chunking failed)
  segments = input.segments;
}

const items = segments.map(segment => ({
  json: {
    ...segment,
    jobId: input.jobId,
    totalSegments: segments.length,
    traite: input.traite,
    page: input.page,
    section: input.section,
    commentator: input.commentator,
    sourceLanguage: input.sourceLanguage,
    targetLanguage: input.targetLanguage,
    apiKey: input.apiKey,
    openaiApiKey: input.openaiApiKey,
    context: input.context,
    metadata: input.metadata,
    model: input.model,
    provider: input.provider,    
    pipelineType: input.pipelineType
  }
}));

return items;

// Use original segments directly (no chunking)
const input = $('Parse Input').first().json;

const items = input.segments.map(segment => ({
  json: {
    ...segment,
    jobId: input.jobId,
    totalSegments: input.totalSegments,
    traite: input.traite,
    page: input.page,
    section: input.section,
    commentator: input.commentator,
    sourceLanguage: input.sourceLanguage,
    targetLanguage: input.targetLanguage,
    apiKey: input.apiKey,
    openaiApiKey: input.openaiApiKey,
    context: input.context,
    metadata: input.metadata,
    model: input.model,
    provider: input.provider,    
    pipelineType: input.pipelineType
  }
}));

return items;

// Phase 2: Prepare save payload(s) - handle EN pivot generation
const loopItem = $('Loop Segments').first().json;
// Deux sources : Call Translate Worker (segment normal) OU le segment déjà réassemblé
// (long segment pré-traduit). On détecte via preTranslated.
const translateResult = loopItem.preTranslated
  ? { translation: loopItem.translation, success: true, method: loopItem.method || 'chunked_reassembled', generated_english: false }
  : $input.first().json;

// Base payload for target language translation
const targetPayload = {
  jobId: loopItem.jobId,
  segmentIndex: loopItem.index,
  totalSegments: loopItem.totalSegments,
  translation: translateResult.translation,
  segment_id: loopItem.segment_id,
  commentary_id: loopItem.commentary_id,
  source_text: loopItem.source_text,
  targetLanguage: loopItem.targetLanguage,
  model: loopItem.model,
  provider: loopItem.provider,
  metadata: loopItem.metadata,
  isChunk: loopItem.isChunk || false,
  pipelineType: loopItem.pipelineType,
  method: translateResult.method || 'unknown'
};

// Phase 2: If EN was generated, we need to save it first
const hasGeneratedEnglish = translateResult.generated_english === true && translateResult.english_pivot;

if (hasGeneratedEnglish) {
  // Return TWO items: first EN save, then target language save
  const englishPayload = {
    jobId: loopItem.jobId,
    segmentIndex: loopItem.index,
    totalSegments: loopItem.totalSegments,
    translation: translateResult.english_pivot,
    segment_id: loopItem.segment_id,
    commentary_id: loopItem.commentary_id,
    source_text: loopItem.source_text,
    targetLanguage: 'en',
    model: loopItem.model,
    provider: loopItem.provider,
    metadata: { ...loopItem.metadata, is_generated_pivot: true },
    isChunk: false,
    pipelineType: 'en_pivot_generation',
    method: 'structured_generation',
    isEnglishPivot: true
  };

  return [
    { json: englishPayload },
    { json: { ...targetPayload, hasEnglishPivotSaved: true } }
  ];
}

// No EN generation - just save target translation
return [{ json: targetPayload }];

// Progression ET verdict du segment courant.
//
// Deux branches convergent ici et une seule s'exécute par tour :
//   Call Error Handler → torah-error rend { error_logged: true }  → échec traduction
//   Call Save Worker   → torah-save  rend { success, translation_id, … }
//
// C'est la seule distinction disponible sans nœud supplémentaire, et elle est
// portée par la réponse elle-même — pas par un ordre d'exécution.

const loopItem = $('Loop Segments').first().json;
const amont = $input.first().json;

const current = loopItem.index + 1;
const total = loopItem.totalSegments;
const percentage = Math.round((current / total) * 100);

let ok = true;
let cause = null;
let detail = null;

if (amont && amont.error_logged === true) {
  // Le gestionnaire d'erreurs a journalisé : la TRADUCTION a échoué.
  ok = false;
  cause = 'traduction';
  detail = loopItem.longError || 'traduction en échec';
} else {
  // Réponse de torah-save. Avec onError=continueRegularOutput, un appel raté
  // n'émet pas la forme attendue : l'absence de success vaut échec, jamais succès.
  const echecSave = !amont
    || amont.success === false
    || (amont.error && amont.error.code)
    || (amont.success !== true && !amont.translation_id);
  if (echecSave) {
    ok = false;
    cause = 'sauvegarde';
    detail = (amont && (amont.error?.message || amont.message)) || 'sauvegarde non confirmée';
  }
}

return [{
  json: {
    jobId: loopItem.jobId,
    current: current,
    total: total,
    percentage: percentage,
    isLast: current >= total,
    // Verdict du segment, relu par Consigner Résultat après le PATCH de progression.
    resultat: {
      index: loopItem.index,
      segment_id: loopItem.segment_id || null,
      commentary_id: loopItem.commentary_id || null,
      ok: ok,
      cause: cause,
      detail: detail
    }
  }
}];

// Pré-traduit les segments TROP LONGS (needsChunk) : découpe via le Chunk Worker,
// traduit chaque morceau via le Translate Worker, RÉASSEMBLE en UNE traduction.
// Indispensable car le save est keyé par commentary_id (une ligne) : sauver N morceaux
// sous le même id écraserait tout sauf le dernier. Les segments normaux passent inchangés.
const items = $input.all().map(i => i.json);
const nwh = $env.N8N_WEBHOOK_URL || 'http://localhost:5678';

const call = async (path, body) => this.helpers.httpRequest({
  method: 'POST', url: nwh + '/webhook/' + path, body, json: true, timeout: 300000,
});

const out = [];
for (const seg of items) {
  if (!seg.needsChunk) { out.push(seg); continue; }

  const ctx = { traite: seg.traite, page: seg.page, section: seg.section, commentator: seg.commentator };

  // 1. découper (Claude Smart Split — coupe sémantique)
  let chunkResp;
  try {
    chunkResp = await call('torah-chunk', {
      job_id: seg.jobId, text: seg.text, segment_id: seg.segment_id,
      threshold: seg.chunkThreshold, api_key: seg.apiKey, context: ctx,
    });
  } catch (e) { chunkResp = null; }

  if (!chunkResp || !chunkResp.success || !Array.isArray(chunkResp.segments) || !chunkResp.segments.length) {
    out.push({ ...seg, preTranslated: true, translation: null, longError: 'chunk_failed' });
    continue;
  }

  // 2. traduire chaque morceau DANS L'ORDRE
  const parts = [];
  let failed = null;
  for (const chunk of chunkResp.segments) {
    let tr;
    try {
      tr = await call('torah-translate', {
        job_id: seg.jobId, segment_id: seg.segment_id, text: chunk.text,
        reference_translation: null,
        source_language: seg.sourceLanguage, target_language: seg.targetLanguage,
        api_key: seg.apiKey, model: seg.model, context: ctx, metadata: seg.metadata,
      });
    } catch (e) { tr = null; }
    if (!tr || !tr.success || !tr.translation) { failed = 'chunk_translate_failed'; break; }
    parts.push(tr.translation);
  }

  // 3. réassembler
  out.push({
    ...seg, preTranslated: true,
    translation: failed ? null : parts.join('\n\n'),
    longError: failed,
    isChunk: false,
    chunksReassembled: chunkResp.segments.length,
    method: 'chunked_reassembled',
  });
}
return out.map(json => ({ json }));

const pd = $('Parse Input').first().json;
const rawBody = ($('Webhook Trigger').first().json.body) || $('Webhook Trigger').first().json || {};
const languageNames = {
  'fr': 'français',
  'en': 'English',
  'es': 'español',
  'he': 'hébreu',
  'ar': 'araméen',
  'de': 'allemand',
  'it': 'italien'
};
const sName = languageNames[pd.sourceLanguage] || pd.sourceLanguage;
const tName = languageNames[pd.targetLanguage] || pd.targetLanguage;

// Le commentateur et la référence se prennent SUR L'ITEM quand il les porte, et
// seulement à défaut sur l'en-tête de la requête. Un lot mixte — versets et
// commentaires dans le même appel — recevait sinon le même commentateur pour
// tout le monde, y compris les versets, ce qui faussait le contexte du prompt.
const items = (pd.segments || []).map(s => ({
  commentary_id: s.commentary_id,
  segment_id: s.segment_id,
  segmentText: s.text,
  sourceLangName: sName,
  targetLangName: tName,
  traite: s.traite || pd.traite,
  page: s.page || pd.page,
  metadata: {
    // Un verset n'a pas de commentateur : ne pas lui coller celui de l'en-tête.
    commentator: s.commentary_id ? (s.commentator || pd.commentator) : (s.commentator || null)
  }
}));
const channelId = (pd.context && pd.context.channel_id) || (pd.metadata && pd.metadata.channel_id) || null;
// job_type doit remonter jusqu'au dispatcher : /api/v2/jobs n'accepte qu'une
// énumération fermée. Parse Input le DÉDUIT désormais du contenu, donc la valeur
// transmise ici est toujours valide, quoi qu'ait envoyé l'appelant.
// model : même repli que le mode direct. Sans lui, torah-translate-batch refuse
// en 400 alors que le mode direct, lui, fonctionne — asymétrie invisible à
// l'appelant, qui ne sait pas de quel côté du seuil de 50 il se trouve.
// L'appairage n'est relayé QUE s'il a été demandé. Sans cette condition, le
// metadata de l'appelant interne (Torah Translate Page en envoie un pour son
// propre usage : reference, request_id…) se mettrait à circuler jusqu'au lot
// Anthropic, où il n'a rien à faire. D'où aussi client_metadata imbriqué plutôt
// que fusionné : les deux ne doivent jamais se mélanger.
const appairage = pd.correlationId
  ? { correlation_id: pd.correlationId, client_metadata: pd.metadata || {} }
  : {};

return {
  items,
  ...appairage,
  job_type: pd.jobType,
  api_key: pd.apiKey,
  // pd.model, PAS rawBody.model : Parse Input a déjà appliqué son repli
  // (body.model || 'claude-sonnet-4-6'). Relire le body brut contournait ce
  // parsing et laissait passer un undefined, que torah-translate-batch refuse
  // en 400 — alors que le mode direct, lui, disposait de la valeur repliée.
  model: pd.model,
  // Provenance de la traduction, consommée par /api/translations/save-batch côté
  // callback (n8n-workflows#443). Sans ce relais, le dispatcher les déduisait à
  // l'aveugle et le mode Router n'en bénéficiait pas du tout.
  provider: pd.provider,
  target_language: pd.targetLanguage,
  project_id: pd.projectId,
  callback_channel_id: channelId
};

// Ce que ce nœud rend est ce que la boucle ACCUMULE : splitInBatches conserve les
// items qu'on lui renvoie et les restitue tous sur sa sortie « done ». C'est là que
// le bilan devient calculable.
//
// La lecture passe par $('Calc Progress') et non $json : le nœud amont est le PATCH
// de progression, dont la réponse HTTP a remplacé l'item.
return [{ json: $('Calc Progress').first().json.resultat }];

// Sortie « done » de la boucle : $input.all() rend un item par segment traité,
// tel que Consigner Résultat l'a renvoyé.
//
// Le job concluait jusqu'ici sur Is Last?, qui ne regarde que l'index : un lot dont
// aucune traduction n'aboutissait ressortait « completed ». Observé sur
// job_msoutt40emb72j — 2 segments, 0 traduction, statut completed.

const resultats = $input.all().map(i => i.json).filter(r => r && typeof r.index === 'number');
resultats.sort((a, b) => a.index - b.index);

const total = resultats.length;
const okCount = resultats.filter(r => r.ok).length;
const failCount = total - okCount;

// Vingt premiers échecs : de quoi retraiter sans gonfler le job.
const echecs = resultats.filter(r => !r.ok).slice(0, 20).map(r => ({
  index: r.index,
  segment_id: r.segment_id,
  commentary_id: r.commentary_id,
  cause: r.cause,
  detail: r.detail
}));

// Aucun succès vaut échec du job, pas achèvement. Un succès partiel reste
// « completed », l'appelant disposant du détail pour retraiter.
//
// « failed » suppose que le job soit en « processing » : /api/v2/jobs refuse la
// transition depuis « pending » (INVALID_STATE_TRANSITION, vérifié). Set Processing
// s'exécute sur les DEUX branches de Needs Job Creation?, donc c'est toujours le cas —
// sauf si ce PATCH-là a lui-même échoué, auquel cas il n'y a de toute façon pas de
// job à conclure.
const statut = (total > 0 && okCount === 0) ? 'failed' : 'completed';

return [{
  json: {
    jobId: $('Parse Input').first().json.jobId,
    statut: statut,
    total: total,
    ok_count: okCount,
    fail_count: failCount,
    echecs: echecs
  }
}];

// ============================================
// NORMALISER RÉPONSE — contrat de soumission (azy.daily#225)
// ============================================
//
// Le plugin bascule en fire-and-forget : il n'appelle plus torah-job-status et
// attend un événement sur llm:results:stream. Cette réponse est donc le SEUL
// moment où il apprend qu'une soumission a échoué.
//
// Un 202 émis avant la soumission aurait été aveugle : clé invalide, quota ou
// Anthropic indisponible seraient devenus silencieux, et le plugin aurait attendu
// indéfiniment un événement qui ne serait jamais venu. La soumission coûte ~2 s
// (mesuré) — l'attendre ne coûte rien et rend l'échec visible tout de suite.

const brut = $input.first().json || {};

// Dispatch Batch est en onError=continueRegularOutput : un appel en échec n'émet
// pas la réponse du dispatcher mais l'objet d'erreur, sans statusCode.
let code = brut.statusCode;
if (code === undefined) {
  const msg = String(brut?.error?.message || brut?.message || '');
  const m = msg.match(/(\d{3})\s*-\s*/);
  code = m ? parseInt(m[1], 10) : ((brut?.error || brut?.code) ? 502 : 200);
}
const corps = brut.body || brut;

const pd = $('Parse Input').first().json;
const correlationId = corps.correlation_id || pd.correlationId || null;
const accepte = code < 400 && corps.success !== false && !corps.error;

if (!accepte) {
  const e = corps.error || {};
  return [{ json: {
    accepted: false,
    batch: true,
    job_id: corps.job_id || pd.jobId || null,
    correlation_id: correlationId,
    error: {
      code: Number(e.code) || (code >= 400 ? code : 502),
      message: e.message || String(brut?.error?.message || 'Soumission du lot impossible'),
      status: e.status || 'BATCH_SUBMIT_ERROR'
    },
    _httpCode: Number(e.code) || (code >= 400 ? code : 502)
  }}];
}

return [{ json: {
  accepted: true,
  batch: true,
  job_id: corps.job_id || pd.jobId || null,
  correlation_id: correlationId,
  count: corps.count || pd.totalSegments || 0,
  // Conservés pour retrouver le lot si le suivi par job casse.
  batch_id: corps.batch_id || null,
  _httpCode: 202
}}];

// Parse and validate input
const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

const CHUNK_THRESHOLD = 10000;

// Generate job_id if not provided
const jobIdProvided = !!body.job_id;
const jobId = body.job_id || 'job_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);
const projectId = headers['x-project-id'] || body.project_id || 'default';

// Determine pipeline type
let pipelineType = 'unknown';
let segments = [];
let needsChunking = false;
let totalSegments = 0;

if (body.segments && Array.isArray(body.segments) && body.segments.length > 0) {
  // Batch mode: multiple segments (commentaries)
  pipelineType = 'batch';
  segments = body.segments.map((s, idx) => ({
    index: idx,
    text: typeof s === 'string' ? s : (s.text || s.text_hebrew || s.hebrew_text),
    segment_id: s.segment_id || null,
    commentary_id: s.commentary_id || null,
    source_text: typeof s === 'string' ? s : null,
    // RFC bilingual-translations-en-pivot: EN pivot for quality
    reference_translation: s.reference_translation || null,
    char_count: (typeof s === 'string' ? s : (s.text || s.text_hebrew || s.hebrew_text || '')).length
  }));

  // Check if any segment is too long
  const tooLongSegment = segments.find(s => s.char_count > CHUNK_THRESHOLD);
  if (tooLongSegment) {
    return [{
      json: {
        valid: false,
        error: {
          code: 400,
          message: `Segment ${tooLongSegment.index} is too long (${tooLongSegment.char_count} chars). Max: ${CHUNK_THRESHOLD}. Use chunking for long texts.`
        }
      }
    }];
  }

  totalSegments = segments.length;

} else if (body.text) {
  // Single text mode
  const textLength = body.text.length;

  if (textLength > CHUNK_THRESHOLD) {
    pipelineType = 'chunk_then_translate';
    needsChunking = true;
    // Segments will be created by Chunk Worker
    segments = [{ index: 0, text: body.text, segment_id: body.segment_id || null, source_text: body.text, char_count: textLength }];
    totalSegments = 1; // Will be updated after chunking
  } else {
    pipelineType = 'translate_single';
    segments = [{
      index: 0,
      text: body.text,
      segment_id: body.segment_id || null,
      source_text: body.text,
      char_count: textLength
    }];
    totalSegments = 1;
  }
} else {
  return [{
    json: {
      valid: false,
      error: { code: 400, message: 'Either segments[] or text is required' }
    }
  }];
}

return [{
  json: {
    valid: true,
    jobId: jobId,
    jobIdProvided: jobIdProvided,
    needsJobCreation: !jobIdProvided,
    projectId: projectId,
    jobType: body.job_type || 'translation',
    pipelineType: pipelineType,
    needsChunking: needsChunking,
    segments: segments,
    totalSegments: totalSegments,
    traite: body.traite,
    page: body.page,
    section: body.section,
    commentator: body.commentator,
    sourceLanguage: body.source_language || 'he',
    targetLanguage: body.target_language || 'fr',
    apiKey: body.api_key,
    openaiApiKey: body.openai_api_key,
    context: body.context || {},
    metadata: body.metadata || {},
    requestId: body.request_id,
    model: body.model || 'claude-sonnet-4-6',
    provider: body.provider || 'anthropic',
    chunkThreshold: CHUNK_THRESHOLD
  }
}];

// Prepare segments for translation loop
const input = $('Parse Input').first().json;
const chunkResult = $input.first().json;

let segments = [];

// Check if chunking was done
if (chunkResult.segments && Array.isArray(chunkResult.segments)) {
  // Chunked segments from Chunk Worker
  segments = chunkResult.segments.map((s, idx) => ({
    index: idx,
    text: s.text,
    segment_id: input.segments[0]?.segment_id,
    source_text: input.segments[0]?.source_text,
    char_count: s.text?.length || 0,
    isChunk: true,
    totalChunks: chunkResult.segments.length
  }));
} else {
  // Use original segments (no chunking needed or chunking failed)
  segments = input.segments;
}

const items = segments.map(segment => ({
  json: {
    ...segment,
    jobId: input.jobId,
    totalSegments: segments.length,
    traite: input.traite,
    page: input.page,
    section: input.section,
    commentator: input.commentator,
    sourceLanguage: input.sourceLanguage,
    targetLanguage: input.targetLanguage,
    apiKey: input.apiKey,
    openaiApiKey: input.openaiApiKey,
    context: input.context,
    metadata: input.metadata,
    model: input.model,
    provider: input.provider,    
    pipelineType: input.pipelineType
  }
}));

return items;

// Use original segments directly (no chunking)
const input = $('Parse Input').first().json;

const items = input.segments.map(segment => ({
  json: {
    ...segment,
    jobId: input.jobId,
    totalSegments: input.totalSegments,
    traite: input.traite,
    page: input.page,
    section: input.section,
    commentator: input.commentator,
    sourceLanguage: input.sourceLanguage,
    targetLanguage: input.targetLanguage,
    apiKey: input.apiKey,
    openaiApiKey: input.openaiApiKey,
    context: input.context,
    metadata: input.metadata,
    model: input.model,
    provider: input.provider,    
    pipelineType: input.pipelineType
  }
}));

return items;

// Phase 2: Prepare save payload(s) - handle EN pivot generation
const loopItem = $('Loop Segments').first().json;
const translateResult = $input.first().json;

// Base payload for target language translation
const targetPayload = {
  jobId: loopItem.jobId,
  segmentIndex: loopItem.index,
  totalSegments: loopItem.totalSegments,
  translation: translateResult.translation,
  segment_id: loopItem.segment_id,
  commentary_id: loopItem.commentary_id,
  source_text: loopItem.source_text,
  targetLanguage: loopItem.targetLanguage,
  model: loopItem.model,
  provider: loopItem.provider,
  metadata: loopItem.metadata,
  isChunk: loopItem.isChunk || false,
  pipelineType: loopItem.pipelineType,
  method: translateResult.method || 'unknown'
};

// Phase 2: If EN was generated, we need to save it first
const hasGeneratedEnglish = translateResult.generated_english === true && translateResult.english_pivot;

if (hasGeneratedEnglish) {
  // Return TWO items: first EN save, then target language save
  const englishPayload = {
    jobId: loopItem.jobId,
    segmentIndex: loopItem.index,
    totalSegments: loopItem.totalSegments,
    translation: translateResult.english_pivot,
    segment_id: loopItem.segment_id,
    commentary_id: loopItem.commentary_id,
    source_text: loopItem.source_text,
    targetLanguage: 'en',
    model: loopItem.model,
    provider: loopItem.provider,
    metadata: { ...loopItem.metadata, is_generated_pivot: true },
    isChunk: false,
    pipelineType: 'en_pivot_generation',
    method: 'structured_generation',
    isEnglishPivot: true
  };

  return [
    { json: englishPayload },
    { json: { ...targetPayload, hasEnglishPivotSaved: true } }
  ];
}

// No EN generation - just save target translation
return [{ json: targetPayload }];

// Update progress after each segment
const loopItem = $('Loop Segments').first().json;
const current = loopItem.index + 1;
const total = loopItem.totalSegments;
const percentage = Math.round((current / total) * 100);

return [{
  json: {
    jobId: loopItem.jobId,
    current: current,
    total: total,
    percentage: percentage,
    isLast: current >= total
  }
}];
